begin;
select no_plan();
insert into organizations(id,name) values ('39920000-0000-0000-0000-000000000001','Authority A'),('39920000-0000-0000-0000-000000000002','Authority B');
insert into auth.users(id,email) values ('39920000-0000-0000-0000-000000000011','authority@example.invalid');
insert into profiles(id,org_id,full_name,email,role) values ('39920000-0000-0000-0000-000000000011','39920000-0000-0000-0000-000000000001','Admin','authority@example.invalid','Admin');
insert into procurements(id,org_id,title,status,requested_by_id) values ('39920000-0000-0000-0000-000000000021','39920000-0000-0000-0000-000000000001','Historical','Paid','39920000-0000-0000-0000-000000000011');
insert into purchase_requests(id,procurement_id,import_key,import_batch_id) values ('39920000-0000-0000-0000-000000000041','39920000-0000-0000-0000-000000000021','legacy','39920000-0000-0000-0000-000000000099');
insert into purchase_requests(id,procurement_id,import_key) values ('39920000-0000-0000-0000-000000000042','39920000-0000-0000-0000-000000000021','legacy-null');
insert into procurement_import_runs(id,org_id,identity_version) values ('39920000-0000-0000-0000-000000000099','39920000-0000-0000-0000-000000000001',2), ('39920000-0000-0000-0000-000000000098','39920000-0000-0000-0000-000000000002',2);
select is((select import_identity_version from purchase_requests where id='39920000-0000-0000-0000-000000000041'),null::smallint,'registering reused identifier leaves existing keyed record unknown');
select is((select import_identity_version from purchase_requests where id='39920000-0000-0000-0000-000000000042'),null::smallint,'null batch remains unknown');
select isnt(public.start_procurement_import_run('39920000-0000-0000-0000-000000000001'),null::uuid,'direct BYPASSRLS session registers an explicit organization');
set local role service_role;
set local request.jwt.claims = '{"role":"service_role"}';
select ok(public.actor_bypasses_rls(),'service authority bypasses RLS');
create temporary table service_run as select public.start_procurement_import_run('39920000-0000-0000-0000-000000000001') id;
select isnt((select id from service_run),null::uuid,'trusted authority registers explicit organization');
select throws_ok($$select public.start_procurement_import_run()$$,'42501',null,'trusted authority supplies an organization');
insert into purchase_requests(id,procurement_id,status,import_key,import_batch_id) values ('39920000-0000-0000-0000-000000000043','39920000-0000-0000-0000-000000000021','Closed','historical',(select id from service_run));
select is((select import_identity_facts from purchase_requests where id='39920000-0000-0000-0000-000000000043'),'[null,"Closed",null,null]'::jsonb,'terminal historical insert captures actual typed values');
select is((select count(*) from procurement_status_events where procurement_id='39920000-0000-0000-0000-000000000021'),0::bigint,'historical insert adds no status event');
insert into purchase_requests(id,procurement_id,import_key,import_batch_id) values ('39920000-0000-0000-0000-000000000044','39920000-0000-0000-0000-000000000021','foreign-run','39920000-0000-0000-0000-000000000098');
select is((select import_identity_version from purchase_requests where id='39920000-0000-0000-0000-000000000044'),null::smallint,'other organization run does not mark a record');
select lives_ok($$update purchase_requests set import_identity_facts='["authority"]'::jsonb where id='39920000-0000-0000-0000-000000000043'$$,'trusted authority retains its explicit exemption');
select throws_ok($$insert into purchase_requests(id,procurement_id,import_key,import_batch_id) values ('39920000-0000-0000-0000-000000000043','39920000-0000-0000-0000-000000000021','different-key',(select id from service_run))$$,'23505',null,'unrelated unique constraint retains its original error');
select throws_ok($$delete from procurement_import_runs where id=(select id from service_run)$$,'42501',null,'service API role has no run delete grant');
reset role;
grant insert on purchase_requests to authenticated;
grant update(import_identity_version,import_identity_facts,import_key,import_batch_id,procurement_id) on purchase_requests to authenticated;
set local role authenticated;
set local request.jwt.claims = '{"sub":"39920000-0000-0000-0000-000000000011","role":"authenticated"}';
select is((select count(*) from purchase_requests where import_key in ('legacy','legacy-null')),2::bigint,'unknown keyed and null-batch records remain searchable');
select throws_ok($$insert into procurement_import_runs(id,org_id,identity_version) values ('39920000-0000-0000-0000-000000000097','39920000-0000-0000-0000-000000000001',2)$$,'42501',null,'ordinary role cannot insert a run');
select throws_ok($$delete from procurement_import_runs where id='39920000-0000-0000-0000-000000000099'$$,'42501',null,'ordinary role cannot delete a run');
select throws_ok($$insert into purchase_requests(procurement_id,import_key,import_batch_id,import_identity_version,import_identity_facts) values ('39920000-0000-0000-0000-000000000021','supplied','39920000-0000-0000-0000-000000000099',2,'[]'::jsonb)$$,'42501',null,'ordinary role cannot supply creation metadata');
select throws_ok($$update purchase_requests set import_identity_facts='[]'::jsonb where id='39920000-0000-0000-0000-000000000043'$$,'42501',null,'ordinary role cannot alter creation facts');
select throws_ok($$update purchase_requests set import_key='changed' where id='39920000-0000-0000-0000-000000000043'$$,'42501',null,'ordinary role cannot alter marked key');
select throws_ok($$update purchase_requests set import_identity_version=2 where id='39920000-0000-0000-0000-000000000041'$$,'42501',null,'ordinary role cannot mark an existing record');
select * from finish();
rollback;
